create extension if not exists vector with schema extensions;
create extension if not exists pgcrypto with schema extensions;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, career_goal text, constraints jsonb not null default '{}'::jsonb, preferred_locations text[] not null default '{}', salary_min integer, salary_max integer, weekly_hours integer not null default 5 check(weekly_hours between 1 and 80), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.resumes(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, label text not null, file_path text, file_type text, parsed jsonb not null default '{}'::jsonb, version integer not null default 1, is_active boolean not null default true, created_at timestamptz not null default now());
 create table public.target_roles(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, seniority text, industry text, target_companies text[] not null default '{}', location text, salary_min integer, salary_max integer, is_active boolean not null default true, embedding extensions.vector(768), created_at timestamptz not null default now());
create table public.job_postings(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, target_role_id uuid references public.target_roles(id) on delete set null, source text not null, source_id text, url text not null, content_hash text not null, title text not null, company text, location text, salary_min integer, salary_max integer, posted_at timestamptz, raw_ad text not null default '', requirements jsonb not null default '[]'::jsonb, embedding extensions.vector(768), fetched_at timestamptz not null default now(), unique(user_id,content_hash));
create table public.skill_requirements(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, posting_id uuid not null references public.job_postings(id) on delete cascade, canonical_skill text not null, importance text not null default 'must-have', confidence numeric not null default 0.8, evidence text, embedding extensions.vector(768), created_at timestamptz not null default now(), unique(posting_id,canonical_skill));
create table public.user_skills(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, resume_id uuid references public.resumes(id) on delete set null, name text not null, canonical_skill text not null, level text not null, evidence text not null, source text not null check(source in('resume','project','user')), confirmed boolean not null default false, embedding extensions.vector(768), created_at timestamptz not null default now());
create table public.skill_gaps(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, target_role_id uuid references public.target_roles(id) on delete cascade, canonical_skill text not null, posting_frequency integer not null default 0, role_relevance numeric not null default 0, user_proximity numeric not null default 0, time_to_learn numeric not null default 0, priority numeric not null default 0, bucket text not null default 'nice-to-have', source_posting_ids uuid[] not null default '{}', updated_at timestamptz not null default now());
create table public.learning_plan(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, target_role_id uuid references public.target_roles(id) on delete cascade, week integer not null, objective text not null, activities jsonb not null default '[]'::jsonb, resources jsonb not null default '[]'::jsonb, deliverable text not null, status text not null default 'pending', due_date date, completed_at timestamptz, created_at timestamptz not null default now());
create table public.portfolio_projects(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, target_role_id uuid references public.target_roles(id) on delete cascade, title text not null, problem_statement text not null, dataset_source text, deliverable text, success_metric text, readme_outline jsonb not null default '[]'::jsonb, interview_talking_points jsonb not null default '[]'::jsonb, mapped_gaps text[] not null default '{}', status text not null default 'planned', repo_url text, demo_url text, metric_met boolean not null default false, created_at timestamptz not null default now());
create table public.interview_sessions(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, target_role_id uuid references public.target_roles(id) on delete set null, question_type text not null, question text not null, transcript jsonb not null default '[]'::jsonb, overall_score numeric, created_at timestamptz not null default now());
create table public.interview_answers(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, session_id uuid not null references public.interview_sessions(id) on delete cascade, answer text not null, scores jsonb not null default '{}'::jsonb, strengths jsonb not null default '[]'::jsonb, gaps jsonb not null default '[]'::jsonb, sample_answer text, follow_ups jsonb not null default '[]'::jsonb, created_at timestamptz not null default now());
create table public.applications(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, posting_id uuid references public.job_postings(id) on delete set null, target_role_id uuid references public.target_roles(id) on delete set null, resume_id uuid references public.resumes(id) on delete set null, company text not null, role text not null, company_type text, channel text, jd_cluster text, applied_at date not null default current_date, response_at date, stage text not null default 'applied', outcome text, rejection_reason text, created_at timestamptz not null default now());
create table public.response_insights(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, segment_type text not null, segment_value text not null, sample_size integer not null, response_rate numeric not null, interview_conversion numeric not null, low_confidence boolean not null, calculated_at timestamptz not null default now());
create table public.api_usage(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, provider text not null, period_start date not null, request_count integer not null default 0, tokens_used bigint not null default 0, quota integer not null, updated_at timestamptz not null default now(), unique(user_id,provider,period_start));
create table public.ai_cache(id uuid primary key default gen_random_uuid(), cache_key text unique not null, user_id uuid references auth.users(id) on delete cascade, response jsonb not null, expires_at timestamptz not null, created_by uuid references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.user_corrections(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, field text not null, original_value jsonb, corrected_value jsonb not null, created_at timestamptz not null default now());
create table public.readiness_scores(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, target_role_id uuid references public.target_roles(id) on delete cascade, score integer not null check(score between 0 and 100), score_low integer, score_high integer, component_breakdown jsonb not null, confidence text not null, verdict text not null, change_summary text, event_type text not null, created_at timestamptz not null default now());
create table public.readiness_actions(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, target_role_id uuid references public.target_roles(id) on delete cascade, name text not null, hours numeric not null, current_score integer not null, projected_score integer not null, gain_per_hour numeric not null, simulated_inputs jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.skill_taxonomy(canonical_skill text primary key, aliases text[] not null default '{}', category text not null, embedding extensions.vector(768));
create table public.demo_postings(id text primary key, title text not null, company text not null, location text not null, url text not null, posted_at date not null, requirements text[] not null, description text not null);
insert into public.skill_taxonomy(canonical_skill,aliases,category) values ('SQL',array['Structured Query Language','PostgreSQL','T-SQL'],'data'),('Python',array['Pandas','NumPy','Python programming'],'data'),('Experiment design',array['A/B testing','Experimental design','Causal inference'],'analytics'),('Statistics',array['Statistical analysis','Probability'],'analytics'),('Dashboard design',array['Data visualization','Tableau','Looker','Power BI'],'analytics'),('dbt',array['Data build tool','dbt Core'],'data'),('Stakeholder communication',array['Executive communication','Cross-functional collaboration'],'soft'),('Product analytics',array['Product metrics','Funnel analysis'],'analytics'),('Git',array['Version control','GitHub'],'engineering') on conflict do nothing;
