do $$ declare t text; begin
 alter table public.profiles enable row level security;
 create policy profiles_owner on public.profiles for all using (id = auth.uid()) with check (id = auth.uid());
 foreach t in array array['resumes','target_roles','job_postings','skill_requirements','user_skills','skill_gaps','learning_plan','portfolio_projects','interview_sessions','interview_answers','applications','response_insights','api_usage','user_corrections','readiness_scores','readiness_actions'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('create policy %I on public.%I for all using (user_id = auth.uid()) with check (user_id = auth.uid())',t||'_owner',t);
 end loop;
 alter table public.ai_cache enable row level security;
 create policy ai_cache_read_own on public.ai_cache for select using (created_by = auth.uid());
 create policy ai_cache_insert_own on public.ai_cache for insert with check (created_by = auth.uid());
 create policy ai_cache_update_own on public.ai_cache for update using (created_by = auth.uid()) with check (created_by = auth.uid());
 alter table public.skill_taxonomy enable row level security;
 create policy skill_taxonomy_read on public.skill_taxonomy for select using (true);
 alter table public.demo_postings enable row level security;
 create policy demo_postings_read on public.demo_postings for select using (true);
end $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$
begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email)) on conflict(id) do nothing; return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create index on public.job_postings(user_id,posted_at desc);
create index on public.skill_requirements(user_id,canonical_skill);
create index on public.readiness_scores(user_id,created_at desc);
create index on public.applications(user_id,applied_at desc);
create or replace function public.record_api_usage(p_provider text,p_tokens bigint,p_quota integer default 0) returns void language plpgsql security invoker set search_path=public as $$
declare month_start date := date_trunc('month',now())::date;
begin
 insert into public.api_usage(user_id,provider,period_start,request_count,tokens_used,quota)
 values(auth.uid(),p_provider,month_start,1,greatest(0,p_tokens),greatest(0,p_quota))
 on conflict(user_id,provider,period_start) do update set request_count=api_usage.request_count+1,tokens_used=api_usage.tokens_used+greatest(0,p_tokens),quota=greatest(0,p_quota),updated_at=now();
end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('resumes','resumes',false,10485760,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document']) on conflict(id) do nothing;
create policy resume_storage_read on storage.objects for select using(bucket_id='resumes' and (storage.foldername(name))[1]=auth.uid()::text);
create policy resume_storage_insert on storage.objects for insert with check(bucket_id='resumes' and (storage.foldername(name))[1]=auth.uid()::text);
create policy resume_storage_delete on storage.objects for delete using(bucket_id='resumes' and (storage.foldername(name))[1]=auth.uid()::text);
